        int[] dp = new int[n];
        int result = 1;

        for (int i = 0; i < n; i++) {
            dp[i] = 1;
            for (int j = 0; j < i; j++) {
                if (arr[i] == arr[j] + 1 || arr[i] == arr[j] - 1) {
                    dp[i] = Math.max(dp[i], dp[j] + 1);
