class FindMax {

    public static int findMax(int[] arr, int low, int high) {
        if (low == high) {
            return arr[low];
        }
        int mid = (low + high) / 2;
        int leftMax = findMax(arr, low, mid);
        int rightMax = findMax(arr, mid + 1, high);
        int maxOfLeftAndRight = Math.max(leftMax, rightMax);
        return maxOfLeftAndRight;
    }
}

