class MaxSumSubseq {

    public static int maxSumSubseq(int[] a) {
        int n = a.length;
        if (n == 0) return 0;
        if (n == 1) return a[0];

        int[] dp = new int[n + 1];
        dp[0] = 0; // No elements picked, sum is 0
        dp[1] = a[0]; // Only one element picked

        for (int i = 2; i <= n; i++) {
            dp[i] = Math.max(dp[i - 1], dp[i - 2] + a[i - 1]);
        }
        return dp[n];
    }
}

