        if (n == 0) return 0;

        Arrays.sort(arr);

        int ans = 0;
        int count = 1;

        for (int i = 1; i < n; i++) {
            if (arr[i] == arr[i - 1]) {
                continue;
            }

            if (arr[i] == arr[i - 1] + 1) {
                count++;
            } else {
                ans = Math.max(ans, count);
                count = 1; // Reset count for a new sequence
            }
        }

        ans = Math.max(ans, count);

        return ans;
    }
}

