                    T[i][j] = 0;
                } else if (i < j) {
                    T[i][j] = 0;
                } else if (j == 1) {
                    T[i][j] = i;
                } else {
                    T[i][j] = T[i-1][j] + T[i/2][j-1];
                }
            }
        }
        return T[m][n];
    }
}

