class RearrangeBigger {

    public static Object rearrangeBigger(int n) {
        String s = String.valueOf(n);
        char[] c = s.toCharArray();
        int i = 0;
        while (i < c.length - 1) {
            if (c[i] < c[i + 1]) {
                break;
            }
            i++;
        }
        if (i == c.length - 1) {
            return false;
        }
        int j = c.length - 1;
        while (j > i) {
            if (c[j] > c[i]) {
                break;
            }
            j--;
        }
        char temp = c[i];
        c[i] = c[j];
        c[j] = temp;
        String str = new String(c);
        return Integer.parseInt(str);
    }
}

