class Last {

    public static int last(int[] arr, int x, int n) {
        int i = 0;
        int j = n - 1;
        int result = -1; // to store the last position of x

        while (i <= j) {
            int mid = (i + j) / 2;
            if (arr[mid] == x) {
                result = mid; // update result and continue to search to the right
                i = mid + 1;
            } else if (arr[mid] < x) {
                i = mid + 1;
            } else {
                j = mid - 1;
            }
        }

        return result; // return the last position or -1 if not found
    }
}

